const tick = () => {
  const now = Date.now();
  const drift = now - expectedTime;

  // Adjust next tick based on drift
  if (drift > 1000) {
    expectedTime = now + 1000;
    callback(elapsedSeconds);
  } else {
    callback(elapsedSeconds);
    expectedTime += 1000;
  }

  // Recursively schedule next tick
  timerId = self.setTimeout(tick, Math.max(0, 1000 - drift));
};

